#include "strutil.h"

#include <assert.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    char only_leading[] = "   x";
    assert(strcmp(strutil_trim(only_leading), "x") == 0);

    char only_trailing[] = "x   ";
    assert(strcmp(strutil_trim(only_trailing), "x") == 0);

    char all_space[] = "    ";
    assert(strcmp(strutil_trim(all_space), "") == 0);

    printf("PASS\n");
    return 0;
}

